void decode_object(const Json& json, InputPaidMedia& value) {
    if (!json.is_object()) {
        throw std::invalid_argument("expected union Object");
    }
    if (json.at("type") == "live_photo") {
        value.value.emplace<0>(from_json<InputPaidMediaLivePhoto>(json));
        return;
    }
    if (json.at("type") == "photo") {
        value.value.emplace<1>(from_json<InputPaidMediaPhoto>(json));
        return;
    }
    if (json.at("type") == "video") {
        value.value.emplace<2>(from_json<InputPaidMediaVideo>(json));
        return;
    }
    throw std::invalid_argument("unknown or invalid InputPaidMedia alternative");
}

